[FormControlAttribute('TFMMenuItemsCtrl','/Resources/html/TFMMenuItemsCtrl',classstr(TFMMenuItemsCtrlBuild))]
public class TFMMenuItemsCtrl extends FormTemplateContainerControl
{
    TFMMenuItemsContainerInterface formClass;
    FormProperty        SendAvailableMenuItemsToJavascriptProperty;
    FormProperty        SendSelectedMenuItemsToJavascriptProperty;
    FormProperty        SendSaveRequestToControlToJavascriptProperty;
    FormProperty        SetActiveMenuItemsToJavascriptProperty;
    FormProperty        SendUpdatingToJavascriptProperty;
    Map                 createdMenuItems;
    int                 counter = 0;


}

Method.Source:
protected void new(FormBuildControl _build, FormRun _formRun)
{
    super(_build, _formRun);
    this.setTemplateId('TFMMenuItemsCtrl');
    this.setResourceBundleName('/Resources/html/TFMMenuItemsCtrl');

    SendAvailableMenuItemsToJavascriptProperty = this.addProperty(methodstr(TFMMenuItemsCtrl, SendAvailableMenuItemsToJavascript), Types::String);
    SendSelectedMenuItemsToJavascriptProperty = this.addProperty(methodstr(TFMMenuItemsCtrl, SendSelectedMenuItemsToJavascript), Types::String);
    SendSaveRequestToControlToJavascriptProperty = this.addProperty(methodstr(TFMMenuItemsCtrl, SendSaveRequestToControlToJavascript), Types::String);
    SetActiveMenuItemsToJavascriptProperty = this.addProperty(methodstr(TFMMenuItemsCtrl, SetActiveMenuItemsToJavascript), Types::String);
    SendUpdatingToJavascriptProperty = this.addProperty(methodstr(TFMMenuItemsCtrl, SendUpdatingToJavascript), Types::String);

    this.createdMenuItems = new Map(Types::String, Types::Class);
}

/// <summary>
/// Sends the menu items to the control.
/// </summary>
/// <param name = "promotedMenuItems"></param>
/// <param name = "contextMenuItems"></param>
public void sendMenuItemsToControl(FormDataSource _mobPageMenuItems_ds, TFMMenuItemsContainerInterface _formClass)
{
    TFMMenuConfigContract contract;
    List contextMenuItems = new List(Types::Class);
    List promotedMenuItems = new List(Types::Class);
    TFMPageMenuItems pageItem = _mobPageMenuItems_ds.getFirst() as TFMPageMenuItems;
    TFMPages pages = TFMPagesProvider::getAllPages();
    this.setFormClass(_formClass);

    boolean pageIsInOffline = formClass.currentPage().getConfiguration() && formClass.currentPage().getConfiguration().isOfflineEnabled();

    while(pageItem)
    {
        contract = this.convertToContract(pageItem, pages, pageIsInOffline);
        if(pageItem.PromotedItem)
        {
            promotedMenuItems.addEnd(contract);
        }
        else
        {
            contextMenuItems.addEnd(contract);
        }
        pageItem = _mobPageMenuItems_ds.getNext() as TFMPageMenuItems;
    }

    this.SendSelectedMenuItemsToJavascript(FormJsonSerializer::serializeClass(promotedMenuItems));
    this.SendAvailableMenuItemsToJavascript(FormJsonSerializer::serializeClass(contextMenuItems));

}

[FormPropertyAttribute(FormPropertyKind::Value, 'SendAvailableMenuItemsToJavascript')]
private str SendAvailableMenuItemsToJavascript(str _value = SendAvailableMenuItemsToJavascriptProperty.parmValue())
{
    // making sure to update even if the list is empty. To hide the loader.
    str valueOverride = _value;
    if(_value == '[]')
    {
        valueOverride = '[' + int2str(timeNow()) + ']';
    }
    SendAvailableMenuItemsToJavascriptProperty.setValueOrBinding(valueOverride);
    return SendAvailableMenuItemsToJavascriptProperty.parmValue();
}

/// <summary>
/// Saves the menu items sorting setup.
/// </summary>
/// <param name = "_jsonStr"></param>
[FormCommandAttribute('setMenuItemsSortingSetup')]
public void setMenuItemsSortingSetup(str _jsonStr)
{
    List newMenuSetup = FormJsonSerializer::deserializeCollection(classNum(List), _jsonStr, Types::Class, identifierStr('TFMMenuConfigContract'));
    formClass.saveMenuItemsSetup(newMenuSetup);
}

/// <summary>
/// Sets the active menu item on the javascript control.
/// </summary>
/// <param name = "_value"></param>
[FormPropertyAttribute(FormPropertyKind::Value, 'setActiveMenuItemsToJavascript')]
public str setActiveMenuItemsToJavascript(str _value = SetActiveMenuItemsToJavascriptProperty.parmValue())
{
    SetActiveMenuItemsToJavascriptProperty.setValueOrBinding(_value);
    return SetActiveMenuItemsToJavascriptProperty.parmValue();
}

/// <summary>
/// The javascript control requests the translation based on the _localizationKey and then it is returned to the javascript.
/// </summary>
/// <param name = "_localizationKey"></param>
/// <returns></returns>
[FormCommandAttribute('getTranslation')]
public str getLocalization(str _localizationKey)
{
    str sReturn;
    TFMLocalizationContract contract = new TFMLocalizationContract();

    str labelStr = SysLabel::labelId2String('@TFM:' + _localizationKey);
    contract.parmKey(_localizationKey);
    contract.parmTranslation(labelStr);
    sReturn = FormJsonSerializer::serializeClass(contract);
    return sReturn;
}

/// <summary>
/// Sets the selected menu item id so that the FO can update the datasource.
/// </summary>
/// <param name = "_selectedMenuItemId"></param>
/// <returns></returns>
[FormCommandAttribute('setSelectedMenuItem')]
public str setSelectedMenuItem(str _selectedMenuItemId)
{
    str sReturn = '';
    formClass.setActiveMenuItem(_selectedMenuItemId);
    return sReturn;
}

/// <summary>
/// Calls FO to show the add menu item form lookup page to be able to add a menu item.
/// </summary>
/// <returns></returns>
[FormCommandAttribute('addMenuItem')]
public str addMenuItem(str _value)
{
    str sReturn = '';
    formClass.showAddMenuItemsFormLookup();
    return sReturn;
}

private TFMMenuConfigContract convertToContract(TFMPageMenuItems _pageItem, TFMPages _pages, boolean _pageIsInOfflineMode)
{
    TFMMenuConfigContract contract;
    if(createdMenuItems.exists(_pageItem.MenuPageID))
    {
        contract = createdMenuItems.lookup(_pageItem.MenuPageID);
    }
    else
    {
        contract = new TFMMenuConfigContract();
        contract.parmPageId(_pageItem.MenuPageID);
        contract.parmTitle(TFMListVisualization::getMenuTitle(TFMPageMenuItemsFormHelper::getMenuItemTitleStr(_pageItem, _pages)));
        //contract.parmIconName('https://cdn-icons-png.flaticon.com/128/9393/9393642.png'); //Used for testing
        str iconStr = TFMPageMenuItemsFormHelper::getMenuItemIconStr(_pageItem, _pages);
        contract.parmIconName(TFMDocGetMedia::getURLFromIconName(iconStr));
        contract.parmIsMandatory(_pageItem.Mandatory);
        contract.parmIsOffline(_pageItem.MenuItemType == TFMPageMenuItemTypes::OfflinePageMenuItem);
        contract.parmIsHide(_pageItem.Hide);
        contract.parmPageIsSetupForOffline(_pageIsInOfflineMode);
        contract.parmUpdated(timeNow());
    }

    return contract;
}
